package com.example.familymenu.category.repository;
import com.example.familymenu.category.domain.*; import org.springframework.context.annotation.Profile; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.support.*; import org.springframework.stereotype.Repository; import java.sql.*; import java.util.*;
@Repository @Profile("!memory") public class JdbcCategoryRepository implements CategoryRepository { private final JdbcTemplate jdbc; public JdbcCategoryRepository(JdbcTemplate j){jdbc=j;} private DishCategory map(ResultSet r)throws SQLException{return new DishCategory(r.getLong(1),r.getString(2),r.getInt(3),r.getBoolean(4));} public List<DishCategory> findAll(boolean all){String s="SELECT id,name,sort,enabled FROM dish_categories"+(all?"":" WHERE enabled=TRUE")+" ORDER BY sort,id";return jdbc.query(s,(r,n)->map(r));} public Optional<DishCategory> findById(Long id){List<DishCategory>x=jdbc.query("SELECT id,name,sort,enabled FROM dish_categories WHERE id=?",new Object[]{id},(r,n)->map(r));return x.isEmpty()?Optional.<DishCategory>empty():Optional.of(x.get(0));} public Optional<DishCategory> findByName(String n){List<DishCategory>x=jdbc.query("SELECT id,name,sort,enabled FROM dish_categories WHERE name=?",new Object[]{n},(r,i)->map(r));return x.isEmpty()?Optional.<DishCategory>empty():Optional.of(x.get(0));} public DishCategory save(DishCategory c){if(c.getId()==null){KeyHolder k=new GeneratedKeyHolder();jdbc.update(x->{PreparedStatement p=x.prepareStatement("INSERT INTO dish_categories(name,sort,enabled) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS);p.setString(1,c.getName());p.setInt(2,c.getSort());p.setBoolean(3,c.isEnabled());return p;},k);return new DishCategory(k.getKey().longValue(),c.getName(),c.getSort(),c.isEnabled());}jdbc.update("UPDATE dish_categories SET name=?,sort=?,enabled=? WHERE id=?",c.getName(),c.getSort(),c.isEnabled(),c.getId());return c;} public boolean deleteById(Long id){return jdbc.update("DELETE FROM dish_categories WHERE id=?",id)>0;} }
